package com.x7x7x7x7.easyBagging;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.StringJoiner;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.PostMenuSort;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "EasyBagging",
	description = "Prioritizes Looting Bag contents when picking up ground loot"
)
public class EasyBaggingPlugin extends Plugin
{
	private static final String CONFIG_GROUP = "easybagging";
	static final String CONFIG_KEY_ITEMS = "priorityItems";

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ConfigManager configManager;
	@Inject private ItemManager itemManager;

	// Created fresh on each startUp() so the Swing component re-parents cleanly on re-enable
	private PriorityPanel panel;

	// Synchronized set — modified on client thread, read on render thread; always holds canonical (unnoted) IDs
	private final Set<Integer> priorityItemIds = Collections.synchronizedSet(new HashSet<>());
	// Synchronized map — preserves insertion order for display; keyed by item ID
	private final Map<Integer, PriorityItem> priorityItems = Collections.synchronizedMap(new LinkedHashMap<>());

	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		panel = injector.getInstance(PriorityPanel.class);
		final BufferedImage icon = itemManager.getImage(ItemID.LOOTING_BAG);
		navButton = NavigationButton.builder()
			.tooltip("Loot Bag Priority")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		loadSavedItems();
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		priorityItemIds.clear();
		priorityItems.clear();
		panel = null;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.LOOTING_BAG)
		{
			return;
		}
		updateLootBagItems(event.getItemContainer());
	}

	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		if (priorityItemIds.isEmpty())
		{
			return;
		}

		MenuEntry[] entries = client.getMenuEntries();
		if (entries.length == 0)
		{
			return;
		}

		boolean anyPriority = false;
		for (MenuEntry entry : entries)
		{
			if (isPriority(entry))
			{
				anyPriority = true;
				break;
			}
		}
		if (!anyPriority)
		{
			return;
		}

		// Stable sort by priority rank: rank 0 (top of panel) ends up at the highest index
		// (top of visual menu / default left-click). Non-priority entries sort to lower indices.
		Arrays.sort(entries, (a, b) ->
		{
			int ai = isPriority(a) ? getPriorityRank(a.getIdentifier()) : Integer.MAX_VALUE;
			int bi = isPriority(b) ? getPriorityRank(b.getIdentifier()) : Integer.MAX_VALUE;
			// Reversed: lower rank value → higher sort position → top of menu
			return Integer.compare(bi, ai);
		});
		client.setMenuEntries(entries);
	}

	boolean isPriority(MenuEntry entry)
	{
		return "Take".equals(entry.getOption()) && priorityItemIds.contains(entry.getIdentifier());
	}

	int getPriorityRank(int itemId)
	{
		synchronized (priorityItems)
		{
			int rank = 0;
			for (int id : priorityItems.keySet())
			{
				if (id == itemId)
				{
					return rank;
				}
				rank++;
			}
		}
		return Integer.MAX_VALUE;
	}

	void clearPriorityList()
	{
		priorityItemIds.clear();
		priorityItems.clear();
		configManager.unsetConfiguration(CONFIG_GROUP, CONFIG_KEY_ITEMS);
		panel.refresh();
	}

	void removeItem(int itemId)
	{
		priorityItemIds.remove(itemId);
		priorityItems.remove(itemId);
		saveItems();
		final PriorityPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::refresh);
		}
	}

	void reorderItems(List<Integer> orderedIds)
	{
		synchronized (priorityItems)
		{
			Map<Integer, PriorityItem> copy = new LinkedHashMap<>(priorityItems);
			priorityItems.clear();
			for (int id : orderedIds)
			{
				PriorityItem item = copy.get(id);
				if (item != null)
				{
					priorityItems.put(id, item);
				}
			}
		}
		saveItems();
	}

	Collection<PriorityItem> getPriorityItems()
	{
		synchronized (priorityItems)
		{
			return new ArrayList<>(priorityItems.values());
		}
	}

	private void updateLootBagItems(ItemContainer container)
	{
		boolean changed = false;
		for (Item item : container.getItems())
		{
			int id = item.getId();
			if (id <= 0 || priorityItemIds.contains(id))
			{
				continue;
			}
			priorityItemIds.add(id);
			String name = itemManager.getItemComposition(id).getName();
			priorityItems.put(id, new PriorityItem(id, name));
			changed = true;
		}
		if (changed)
		{
			saveItems();
			final PriorityPanel p = panel;
			if (p != null)
			{
				SwingUtilities.invokeLater(p::refresh);
			}
		}
	}

	private void saveItems()
	{
		synchronized (priorityItems)
		{
			if (priorityItems.isEmpty())
			{
				configManager.unsetConfiguration(CONFIG_GROUP, CONFIG_KEY_ITEMS);
				return;
			}
			StringJoiner joiner = new StringJoiner(",");
			for (int id : priorityItems.keySet())
			{
				joiner.add(String.valueOf(id));
			}
			configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY_ITEMS, joiner.toString());
		}
	}

	// startUp() is called on the EDT — parse IDs here, defer getItemComposition to the client thread
	private void loadSavedItems()
	{
		String saved = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY_ITEMS);
		if (saved == null || saved.isEmpty())
		{
			return;
		}

		List<Integer> ids = new ArrayList<>();
		for (String part : saved.split(","))
		{
			try
			{
				ids.add(Integer.parseInt(part.trim()));
			}
			catch (NumberFormatException e)
			{
				log.debug("Skipping invalid saved item id: {}", part);
			}
		}

		if (ids.isEmpty())
		{
			return;
		}

		priorityItemIds.addAll(ids);

		clientThread.invokeLater(() ->
		{
			for (int id : ids)
			{
				if (!priorityItems.containsKey(id))
				{
					String name = itemManager.getItemComposition(id).getName();
					priorityItems.put(id, new PriorityItem(id, name));
				}
			}
			final PriorityPanel p = panel;
			if (p != null)
			{
				SwingUtilities.invokeLater(p::refresh);
			}
			return true;
		});
	}

}

package com.x7x7x7x7.easyBagging;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import javax.inject.Inject;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

public class PriorityPanel extends PluginPanel
{
	@Inject
	private EasyBaggingPlugin plugin;

	private final JPanel itemListPanel = new JPanel();
	private final JLabel emptyLabel = new JLabel("<html><center>Open your Looting Bag<br>to populate this list.</center></html>");

	// Drag state
	private int dragSourceIndex = -1;
	private int dropTargetIndex = -1;
	// Bounds cached on first drag event so hit-testing stays stable while the drop line moves
	private Rectangle[] itemBoundsAtDragStart = null;

	// Thin amber line that shows the insertion point during drag
	private final JPanel dropLine = buildDropLine();

	private static JPanel buildDropLine()
	{
		JPanel line = new JPanel();
		line.setBackground(new Color(200, 150, 60));
		line.setMaximumSize(new Dimension(Integer.MAX_VALUE, 2));
		line.setPreferredSize(new Dimension(0, 2));
		line.setMinimumSize(new Dimension(0, 2));
		return line;
	}

	public PriorityPanel()
	{
		super(false);
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel("Looting Bag Priorities");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setBorder(new EmptyBorder(10, 10, 8, 10));

		itemListPanel.setLayout(new BoxLayout(itemListPanel, BoxLayout.Y_AXIS));
		itemListPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		itemListPanel.setBorder(new EmptyBorder(0, 5, 5, 5));

		emptyLabel.setForeground(Color.GRAY);
		emptyLabel.setFont(FontManager.getRunescapeSmallFont());
		emptyLabel.setBorder(new EmptyBorder(10, 5, 5, 5));
		emptyLabel.setHorizontalAlignment(JLabel.CENTER);

		JScrollPane scrollPane = new JScrollPane(itemListPanel);
		scrollPane.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scrollPane.setBorder(BorderFactory.createEmptyBorder());
		scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);

		JButton clearButton = new JButton("Clear Priority List");
		clearButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		clearButton.setForeground(Color.WHITE);
		clearButton.setFocusPainted(false);
		clearButton.addActionListener(e -> plugin.clearPriorityList());

		JPanel bottomPanel = new JPanel(new BorderLayout());
		bottomPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		bottomPanel.setBorder(new EmptyBorder(5, 10, 10, 10));
		bottomPanel.add(clearButton, BorderLayout.CENTER);

		add(title, BorderLayout.NORTH);
		add(scrollPane, BorderLayout.CENTER);
		add(bottomPanel, BorderLayout.SOUTH);
	}

	void refresh()
	{
		itemListPanel.removeAll();

		Collection<PriorityItem> items = plugin.getPriorityItems();
		if (items.isEmpty())
		{
			itemListPanel.add(emptyLabel);
		}
		else
		{
			int index = 1;
			for (PriorityItem item : items)
			{
				itemListPanel.add(buildItemRow(item, index++));
			}
		}

		itemListPanel.revalidate();
		itemListPanel.repaint();
	}

	private static final Color ROW_BG = ColorScheme.DARKER_GRAY_COLOR;
	private static final Color ROW_HOVER_BG = new Color(65, 65, 65);
	private static final Color DELETE_HOVER = new Color(200, 80, 80);

	private JPanel buildItemRow(PriorityItem item, int rank)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ROW_BG);
		row.setBorder(BorderFactory.createCompoundBorder(
			new EmptyBorder(2, 0, 2, 0),
			new EmptyBorder(6, 8, 6, 8)
		));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 38));
		row.putClientProperty("itemId", item.getItemId());

		// Rank number — no fixed width so two-digit numbers render fully
		JLabel rankLabel = new JLabel(String.valueOf(rank));
		rankLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		rankLabel.setFont(FontManager.getRunescapeSmallFont());
		rankLabel.setBorder(new EmptyBorder(0, 0, 0, 6));
		rankLabel.setHorizontalAlignment(JLabel.RIGHT);

		// Drag handle — Dialog font renders the braille grip dots correctly
		JLabel handleLabel = new JLabel("⠿");
		handleLabel.setForeground(new Color(100, 100, 100));
		handleLabel.setFont(new Font("Dialog", Font.PLAIN, 14));
		handleLabel.setBorder(new EmptyBorder(0, 0, 0, 7));
		handleLabel.setCursor(Cursor.getPredefinedCursor(Cursor.MOVE_CURSOR));

		JLabel nameLabel = new JLabel(item.getName());
		nameLabel.setForeground(Color.WHITE);
		nameLabel.setFont(FontManager.getRunescapeSmallFont());

		JButton deleteButton = new JButton("×");
		deleteButton.setForeground(new Color(120, 120, 120));
		deleteButton.setBackground(null);
		deleteButton.setBorder(BorderFactory.createEmptyBorder(0, 6, 0, 0));
		deleteButton.setFocusPainted(false);
		deleteButton.setContentAreaFilled(false);
		deleteButton.setBorderPainted(false);
		deleteButton.setFont(new Font("Dialog", Font.BOLD, 14));
		deleteButton.setCursor(Cursor.getPredefinedCursor(Cursor.DEFAULT_CURSOR));
		deleteButton.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				deleteButton.setForeground(DELETE_HOVER);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				deleteButton.setForeground(new Color(120, 120, 120));
			}
		});
		deleteButton.addActionListener(e -> plugin.removeItem(item.getItemId()));

		JPanel leftPanel = new JPanel(new BorderLayout());
		leftPanel.setBackground(ROW_BG);
		leftPanel.add(rankLabel, BorderLayout.WEST);
		leftPanel.add(handleLabel, BorderLayout.CENTER);

		JPanel centerPanel = new JPanel(new BorderLayout());
		centerPanel.setBackground(ROW_BG);
		centerPanel.add(leftPanel, BorderLayout.WEST);
		centerPanel.add(nameLabel, BorderLayout.CENTER);

		row.add(centerPanel, BorderLayout.CENTER);
		row.add(deleteButton, BorderLayout.EAST);

		MouseAdapter hoverHighlight = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(ROW_HOVER_BG);
				leftPanel.setBackground(ROW_HOVER_BG);
				centerPanel.setBackground(ROW_HOVER_BG);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(ROW_BG);
				leftPanel.setBackground(ROW_BG);
				centerPanel.setBackground(ROW_BG);
			}
		};

		DragHandler dragHandler = new DragHandler();
		for (Component c : new Component[]{row, leftPanel, centerPanel, handleLabel, nameLabel, rankLabel})
		{
			c.addMouseListener(dragHandler);
			c.addMouseMotionListener(dragHandler);
			c.addMouseListener(hoverHighlight);
		}

		return row;
	}

	// Walk up to the direct child of itemListPanel, skipping the dropLine, and return its 0-based item index.
	private int getRowIndex(Component comp)
	{
		Component c = comp;
		while (c != null && c.getParent() != itemListPanel)
		{
			c = c.getParent();
		}
		if (c == null || c == dropLine)
		{
			return -1;
		}
		int idx = 0;
		for (int i = 0; i < itemListPanel.getComponentCount(); i++)
		{
			Component panel = itemListPanel.getComponent(i);
			if (panel == dropLine)
			{
				continue;
			}
			if (panel == c)
			{
				return idx;
			}
			idx++;
		}
		return -1;
	}

	private void commitOrder()
	{
		List<Integer> orderedIds = new ArrayList<>();
		for (int i = 0; i < itemListPanel.getComponentCount(); i++)
		{
			Component c = itemListPanel.getComponent(i);
			if (c == dropLine)
			{
				continue;
			}
			if (c instanceof JPanel)
			{
				Object id = ((JPanel) c).getClientProperty("itemId");
				if (id instanceof Integer)
				{
					orderedIds.add((Integer) id);
				}
			}
		}
		plugin.reorderItems(orderedIds);
		refresh();
	}

	private class DragHandler extends MouseAdapter
	{
		@Override
		public void mousePressed(MouseEvent e)
		{
			dragSourceIndex = getRowIndex((Component) e.getSource());
			dropTargetIndex = dragSourceIndex;
			itemBoundsAtDragStart = null;
		}

		@Override
		public void mouseDragged(MouseEvent e)
		{
			if (dragSourceIndex < 0)
			{
				return;
			}

			// Cache bounds once before the drop line is inserted so hit-testing stays stable
			if (itemBoundsAtDragStart == null)
			{
				int count = itemListPanel.getComponentCount();
				itemBoundsAtDragStart = new Rectangle[count];
				for (int i = 0; i < count; i++)
				{
					itemBoundsAtDragStart[i] = new Rectangle(itemListPanel.getComponent(i).getBounds());
				}
			}

			int panelY = SwingUtilities.convertPoint((Component) e.getSource(), e.getPoint(), itemListPanel).y;

			// Find insertion point using the stable cached bounds
			int newTarget = itemBoundsAtDragStart.length;
			for (int i = 0; i < itemBoundsAtDragStart.length; i++)
			{
				if (panelY < itemBoundsAtDragStart[i].y + itemBoundsAtDragStart[i].height / 2)
				{
					newTarget = i;
					break;
				}
			}

			if (newTarget != dropTargetIndex)
			{
				dropTargetIndex = newTarget;
				itemListPanel.remove(dropLine);
				itemListPanel.add(dropLine, Math.min(dropTargetIndex, itemListPanel.getComponentCount()));
				itemListPanel.revalidate();
				itemListPanel.repaint();
			}
		}

		@Override
		public void mouseReleased(MouseEvent e)
		{
			itemListPanel.remove(dropLine);

			if (dragSourceIndex >= 0 && itemBoundsAtDragStart != null)
			{
				int n = itemListPanel.getComponentCount();
				// Adjust for the removal of the source item shifting indices
				int insertAt = dragSourceIndex < dropTargetIndex ? dropTargetIndex - 1 : dropTargetIndex;
				insertAt = Math.max(0, Math.min(insertAt, n - 1));

				if (insertAt != dragSourceIndex)
				{
					Component comp = itemListPanel.getComponent(dragSourceIndex);
					itemListPanel.remove(dragSourceIndex);
					itemListPanel.add(comp, insertAt);
				}
				commitOrder();
			}

			dragSourceIndex = -1;
			dropTargetIndex = -1;
			itemBoundsAtDragStart = null;
			itemListPanel.revalidate();
			itemListPanel.repaint();
		}
	}
}

package com.x7x7x7x7.easyBagging;

import lombok.Data;

@Data
public class PriorityItem
{
	private final int itemId;
	private final String name;

	public PriorityItem(int itemId, String name)
	{
		this.itemId = itemId;
		this.name = name;
	}
}
